(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["fil"] = {"ui":{"skip":"Lumaktaw sa nilalaman","back":"← Bumalik sa AI-gile","lang.button":"Wika: {name}","lang.dialog":"Pumili ng wika","lang.search":"Maghanap ng wika","lang.none":"Walang wikang tumutugma","lang.notYet":"Hindi pa naisasalin ang {name}","theme.aria":"Magpalit ng tema: maliwanag, madilim o itim","theme.toLight":"Lumipat sa maliwanag na tema","theme.toDark":"Lumipat sa madilim na tema","theme.toBlack":"Lumipat sa itim na tema (tunay na itim, magaan sa OLED screen)","words.underline":"I-underline ang mga salitang ito sa page","words.underlineHelp":"I-hover o i-tap ang salitang may tuldok-tuldok para makita kung ano ang ibig sabihin nito.","words.col.todo":"Mga card na napili para sa ngayon: ito ang susunod na sisimulan ng team.","words.col.doing":"May AI na gumagawa sa card na ito ngayon.","words.col.review":"Tapos na ng isang AI ang gawain; chine-check ito ng isa pang AI bago makarating sa iyo.","words.col.verify":"Naghihintay sa iyo: subukan ito at sabihin kung gumagana.","words.col.team":"Ang mga tala o sagot mo, naghihintay na kunin ng team.","words.col.done":"Tapos na at tinanggap.","index.title":"AI-gile: ang AI dev team mo, sa iisang board","index.description":"Ang AI-gile ay kanban board para sa mga AI coding team. Nagtatrabaho sila habang natutulog ka; isang maikling tambak lang ang haharapin mo: mga desisyon, susubukan at aaprubahan.","hero.logoAlt":"Icon ng AI-gile board","hero.h1.html":"Ang AI dev team mo, sa iisang&nbsp;board.","hero.alpha":"🐣 Saradong pre-alpha","hero.alphaTitle":"Maaga pa at hindi pa tapos: salamat sa pagsubok!","hero.lede":"Gumagawa sila habang natutulog ka. Paggising mo, may isang maikling tambak: ilang tanong, ilang susubukan, isa o dalawang purple na diamond. I-click, aprubahan, balik sa kape mo.","dl.windows":"Windows app","dl.browser":"Gamitin sa browser","dl.messenger":"📱 Messenger para sa phone mo","dl.soon":"Malapit na","dl.notify":"🔔 Sabihan ako kapag bukas na","dl.notifySmall":"Alpha o beta","hero.secondary":"Agile, pero hindi kailanman nangangailangan ng stand-up na kape ang team. (Nagsta-stand-up pa rin naman sila.)","pitch.h2":"Ang AI-gile sa dami ng salitang gusto mo","pitch.lede":"Pumili ng haba, mula isang salita hanggang 144. Bawat haba ay sariling paglalarawan, isinulat para sa laki nito. I-drag ang slider o gamitin ang mga arrow key.","pitch.rangeLabel":"Haba sa bilang ng salita","pitch.dice":"🎲 ibang bersyon","pitch.words.one":"{n} salita","pitch.words.other":"{n} salita","pitch.letters.one":"{n} letra","pitch.letters.other":"{n} letra","pitch.chars.one":"{n} karakter","pitch.chars.other":"{n} karakter","count.line.html.one":"{n} card sa board ngayon","count.line.html.other":"{n} card sa board ngayon","people.humans.html.one":"👥 {n} tao","people.humans.html.other":"👥 {n} tao","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agent","people.working.html.one":"⚡ {n} ang nagtatrabaho ngayon","people.working.html.other":"⚡ {n} ang nagtatrabaho ngayon","pre.title":"AI-gile: may binubuo rito","pre.description":"May binubuo rito. Isang board kung saan binubuo ng mga AI team ang hinihingi mo, at tinuturuan ka habang ginagawa nila. Saradong pre-alpha muna kasama ang mga kaibigan.","pre.h1":"May binubuo rito. 🤫","pre.line":"Isang board kung saan binubuo ng mga AI team ang hinihingi mo, at tinuturuan ka habang ginagawa nila. Saradong pre-alpha muna kasama ang mga kaibigan.","pre.btn":"🔔 Sabihan ako kapag bukas na","pre.peek":"Sa likod ng salamin: ang totoong board, live. Bawat card ay isang makulay na bar.","pre.peekFake":"Sa likod ng salamin: ganito ang itsura ng board habang gumagana.","pre.night":"🌙 Ang bantay-gabi ang namamahala · 😴 nagpapahinga ang tao","features.aria":"Ano ang ginagawa nito","f.pile.h":"Isang tambak para sa iyo","f.pile.html":"Dito sa <b>Para sa iyo</b> nakalagay ang lahat ng naghihintay sa iyo, sa lahat ng project: mga tanong, mga susubukan, mga gawaing tao lang ang makakagawa. Sinasabi ng pila mo kung ano ang susunod at gaano ito katagal.","f.sleep.h":"Mga team na nagtatrabaho habang natutulog ka","f.sleep.p":"May lead at team ng mga AI agent ang bawat project. Mag-comment sa isang card at gigising ang team, gagawin ang trabaho, at ibabalik ito na may mga hakbang na masusundan kahit ng pagod na tao.","f.tester.h":"Unang sumusuri ang AI tester","f.tester.p":"Bago may makarating sa iyo, sinusundan ng tester ang mga hakbang sa kopya ng app at ipinapakita ang nakita niya, may screenshot. Tingnan nang mabilis ang mga pumasa at aprubahan sa isang click.","f.proof.h":"Patunay, hindi pangako","f.proof.p":"Ipinapakita ng bawat pasa kung ano ang nagbago: ang mga file, ang diff, ang mga screenshot. Hindi mo na kailangang buksan ang bawat app para malaman kung tapos na.","f.chat.h":"Makipag-chat sa mga lead mo","f.chat.p":"Riles na parang Discord: isang icon bawat project, purple na diamond para sa nangangailangan ng pansin mo. Magpadala ng idea sa lead; gagawin niya itong mga card at plano, may ✅ Go na button.","f.tidy.h":"Nag-aayos nang sarili","f.tidy.p":"Nagsasama ang magkakaugnay na card, naaayos ang magulong pamagat, at pinapanatiling magaan ng token check ang code. Mas kaunting pagpapalit-palit, mas kaunting iisipin.","f.private.h":"Sa iyo, sa computer mo","f.private.li1":"Tumatakbo ang board sa sarili mong makina at ikaw lang ang sinasagot.","f.private.li2":"End-to-end encrypted ang mga pribadong DM sa pagitan ng mga tao.","f.private.li3":"Walang account, walang tracker, walang cookie.","f.lang.h":"Sa wika mo","f.lang.p":"Mahigit 120 wika, mula Dutch, Welsh at Japanese hanggang pirate, Yoda at Klingon, may mabilis na balik sa English para sa mga teknikal na termino.","f.service.h":"Mula sa ideya tungo sa totoong service","f.service.p":"May nabuo ka gamit ang AI na ginagamit na ng mga tao? Markahan ito bilang service at tutulungan ka ng board na patakbuhin ito nang maayos: mga uptime check, pampublikong status page, mga incident na may write-up, mga pagbabagong kailangan ng Go, at mga backup na sinusuri araw-araw. Itinuturo ng Help ang bawat hakbang habang ginagawa mo.","msgr.h2":"AI-gile Messenger: ang team mo, nasa bulsa mo","msgr.p1":"Kausapin ang AI team mo nang hindi binubuksan ang board. Mag-chat sa mga project lead mo at sa mga kaibigan mo, at tingnan ang mga test step ng isang card at sagutin ang mga ito, lahat mula sa phone mo.","msgr.p2":"Para i-pair ito, i-scan ang QR code sa board mo. Unang beses? May friendly na demo chat na magtuturo sa iyo.","msgr.when":"Android muna, tapos isang web version para sa mga phone at iPhone.","msgr.who":"Ang project lead mo","msgr.b1":"Ready na ang fix sa dark mode. Gusto mo ba ang mga test step?","msgr.b2":"Oo, pakibigay!","msgr.b3":"1. Buksan ang Settings. 2. Piliin ang Dark. Mukha bang tama?","tl.aria":"Timeline mula sa unang usapan hanggang sa roadmap","tl.h2":"Mula sa unang chat hanggang sa susunod","tl.lede":"Totoong petsa at oras, sa sarili mong time zone. Pagkatapos ng ngayon, plano na ito, walang pinangakong petsa.","tl.today":"Ngayon","tl.planned":"planado","tl.doing":"ginagawa","tl.cards.one":"{n} card","tl.cards.other":"{n} card","join.h2":"Sumali ka","join.lede":"Ginagawa ang AI-gile ng isang balbas-saradong weirdo na may AuDHD at ilang laban sa mental health, kasama ang napakaraming matiyagang agent. Pribado pa ito sa ngayon, sa saradong alpha kasama ang mga kaibigan. Gusto mo bang sumubok kapag nagbukas na ito?","join.btn":"Magpahayag ng interes","join.small":"Mag-e-email lang kami, wala nang iba","footer.tag":"AI-gile. Walang tracker, walang cookie, walang stand-up na kape.","footer.licence":"Lisensya para sa negosyo","footer.status":"Status","footer.privacy":"Ano ang iniimbak namin","footer.thanks":"Mga call, salamat sa ChilledChat","form.sending":"Ipinapadala…","form.failed":"Hindi iyon umubra: subukan ulit mamaya.","form.offline":"Hindi maabot ang AI-gile: subukan ulit mamaya.","form.keep":"Ginagamit lang namin ito para sumagot sa iyo, saka namin ito buburahin. Walang tracker, walang cookie.","form.keepLink":"Ano ang iniimbak namin","interest.title":"AI-gile: sabihan ako kapag nagbukas ang alpha","interest.description":"Iwan ang email mo para malaman kapag nagbukas ang saradong alpha o beta ng AI-gile.","interest.h1":"🔔 Sabihan ako kapag bukas na","interest.lede":"Nasa saradong pre-alpha ang AI-gile. Iwan ang email mo at susulatan ka namin nang isang beses, kapag may lugar na para sa iyo.","interest.email":"Ang email mo","interest.which":"Aling pagsubok?","interest.alpha":"Saradong alpha: maaga, magaspang, maraming pagbabago","interest.beta":"Beta: mas matatag, mas huli","interest.both":"Alinman, kung ano ang mauna","interest.submit":"Ilagay mo ako sa listahan","interest.thanks":"Salamat! Nasa listahan ka na.","licence.title":"AI-gile: lisensya para sa negosyo","licence.description":"Ginagamit ang AI-gile sa negosyo mo? Mag-apply para sa libreng lisensya para sa negosyo.","licence.h1":"📜 Lisensya para sa negosyo","licence.lede":"Ginagamit ang AI-gile sa trabaho? Sabihin kung sino kayo at ano ang ginagawa ninyo. Kung nakakatulong ito sa kapwa, libre ang lisensya.","licence.company":"Kumpanya","licence.website":"Website","licence.what":"Ano ang ginagawa ninyo","licence.how":"Paano ito nakakatulong sa mundo","licence.email":"Email","licence.submit":"Mag-apply","licence.thanks":"Salamat! Sasagot kami sa email.","status.title":"Status ng AI-gile","status.h1":"Status ng AI-gile","status.quiet":"Tahimik ang lahat","status.intro":"Gumagana ba ang AI-gile ngayon? Tinitingnan ng page na ito ang website, ang pag-share ng board, ang mga tawag at ang download kada 5 minuto.","status.up":"Gumagana (sumagot sa loob ng {ms} ms)","status.slow":"Hindi sumagot sa huling check, sinusubukan ulit","status.down":"Down: hindi sumagot sa huling dalawang check","status.svc.web":"Website","status.svc.web.offers":"Ang site na ito: kung ano ang AI-gile, at ang interest form","status.svc.boards":"Pag-share ng board","status.svc.boards.offers":"Mga pampublikong board, mga mensahe sa pagitan ng magkakaibigan at mga imbitasyon","status.svc.calls":"Mga tawag","status.svc.calls.offers":"Boses, video at screen share sa AI-gile","status.svc.download":"Download","status.svc.download.offers":"Ang Windows installer at mga invite link","status.checking":"Sinusuri…","status.offline":"Hindi maabot ang status service ngayon (susubukan ulit)","status.updated":"na-update {ago}","status.justNow":"ngayon lang","status.min":"{n} min ang nakalipas","status.hours":"{n} oras ang nakalipas","status.days":"{n} araw ang nakalipas","privacy.title":"AI-gile: ano ang iniimbak namin","privacy.h1":"Ano ang iniimbak namin","privacy.lede":"Sa madaling salita: ang ipinapadala mo lang sa amin, at hindi nang matagal.","privacy.only":"Ang ipinapadala mo lang sa amin: ang tina-type mo sa isang form, gaya ng email mo. Wala nang iba tungkol sa iyo.","privacy.sealed":"Sine-seal ito para hindi ito mabasa ng server namin: sa browser mo bago ito umalis (sa mas lumang browser, sa sandaling dumating ito). Ang sarili lang naming board ang makakapagbukas nito.","privacy.server":"Binubura ito sa server sa sandaling makarating ito sa board namin. Anumang naroon pa rin pagkalipas ng 30 araw ay binubura rin.","privacy.board":"Iniimbak lang namin ito sa board namin hanggang makasagot kami sa iyo, saka namin ito buburahin doon din.","privacy.none":"Walang tracker, walang cookie, walang analytics.","privacy.local":"Ang wika mo at ang pinili mong light o dark ay nananatili sa sarili mong browser. Hindi kailanman ipinapadala sa amin ang mga ito.","privacy.ask":"Gusto mo bang mabura ito nang mas maaga? Sumagot ka lang sa email namin at sabihin mo.","live.h2":"Panoorin itong binubuo, live","live.caption":"Nakatago ang bawat card: makikita mo ang hugis ng gawain, hindi ang mga salita.","live.watching.one":"live: {n} ang nanonood","live.watching.other":"live: {n} ang nanonood","live.last.now":"Kalilipat lang ng huling card","live.last.min.one":"Nailipat ang huling card {n} min ang nakalipas","live.last.min.other":"Nailipat ang huling card {n} min ang nakalipas","live.last.hour.one":"Nailipat ang huling card {n} oras ang nakalipas","live.last.hour.other":"Nailipat ang huling card {n} oras ang nakalipas","live.last.day.one":"Nailipat ang huling card {n} araw ang nakalipas","live.last.day.other":"Nailipat ang huling card {n} araw ang nakalipas","live.offline":"Nagpapahinga muna ang live board. Balik ka ulit mamaya.","live.cols":"Backlog|Gagawin|Ginagawa|Chine-check ng team|Para sa iyo na i-test|Para sa team|Tapos na"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robot.","Naipasa."]},{"n":2,"texts":["Kanban, robot.","Agent, organisado.","Ginawang idea."]},{"n":3,"texts":["Kanban para sa robot.","Idea, ginagawang feature.","Libreng kanban ng agent."]},{"n":5,"texts":["Kanban board na pinapatakbo ng agent.","Ikaw ang nagsusulat, agent ang gumagawa.","Libre, lokal, sinubok, medyo kalokohan."]},{"n":8,"texts":["Libreng kanban board kung saan nagtatrabaho ang mga AI agent.","Magsulat ng idea. Gagawin ito ng agent. Ikaw ang aaprub.","Agile para sa isang tao at maraming matiyagang robot."]},{"n":13,"texts":["Kanban board sa computer mo kung saan kinukuha ng mga AI agent ang mga card.","Magsulat ng idea. Gagawin ito ng team ng agent. Susuriin ito ng tester.","Libre, walang account, walang tracker: isang board, ilang robot, at ikaw ang masusunod."]},{"n":21,"texts":["Ang AI-gile ay kanban board para makatrabaho ang mga AI coding agent. Sila ang kumukuha ng mga card; ikaw ang sumusubok at nag-aaprub.","Bawat project ay may lead at team ng mga AI agent. Mag-comment sa kahit anong card at magsisimulang magtrabaho ang team.","Libre at personal na to-do board na tumatakbo sa sarili mong computer. Mga robot ang gumagawa. Ikaw ang nagsasabi ng oo."]},{"n":34,"texts":["Ilalagay mo ang mga idea sa board. Gagawin ng team ng mga AI agent ang mga ito bilang gumaganang feature, susubukan, at ibabalik sa iyo na may mga hakbang na masusubukan mo. Walang matatapos hangga't hindi mo sinasabi.","Gawang-bahay na kanban board ang AI-gile na binuo ni Rich sa tulong ng napakaraming agent na ngayon ay pinamamahalaan nito. Libre ito, tumatakbo sa computer mo, at ibinabahagi sa mga kaibigan, hindi ibinebenta.","Isipin ang karaniwang kanban board, may mga column mula Backlog hanggang Tapos na, maliban na ang mga card ay kinukuha ng mga AI agent. Nag-uulat sila ng progreso, nagtatanong kapag naipit, at laging naghihintay ng pagsang-ayon mo."]},{"n":55,"texts":["Ang AI-gile ay kanban board na ang team ay binubuo ng mga AI agent. May lead ang bawat project na nagpaplano ng trabaho at mga katulong na gumagawa nito. Kapag handa na ang isang feature, sinusubukan ito ng AI tester at kumukuha ng screenshot, saka ito mapupunta sa tambak mo. Aprubahan ito, o mag-comment at gagawin nila ulit.","Nagsimula ito bilang paraan ng isang tao para masubaybayan ang maraming AI coding session nang sabay-sabay, at lumaki bilang tunay na board. Tumatakbo ito sa makina mo, walang account na kailangan, at walang tracker. Libre ito para sa mga kaibigan at sa mga curious. Hindi pa ito tapos, kaya asahan ang ilang gaspang at paminsan-minsang sorpresa.","Heto ang tapat na bersyon. Ikaw pa rin ang kailangang mag-isip ng mga idea, at ikaw pa rin ang kailangang tumingin sa mga resulta. Ang ginagawa ng AI-gile ay lahat ng nasa pagitan: pinapanatili nitong maayos ang mga card, ginigising ang tamang agent kapag nag-comment ka, ipinapakita kung ano mismo ang nagbago, at inilalagay ang lahat sa isang maikling tambak para sa iyo."]},{"n":89,"texts":["Ang AI-gile ay libreng kanban board na pinapatakbo mo sa sarili mong computer. Sa halip na mga tao, bawat project ay may team ng mga AI agent: isang lead na ginagawang mga card at plano ang mga idea mo, at mga katulong na kumukuha ng mga card ayon sa priyoridad. Kapag may nabuo na, sinusundan ng AI tester ang mga hakbang sa pagsubok at ipinapakita sa iyo ang nakita nito. Pagkatapos ay maghihintay ito sa isang tambak na tinatawag na Para sa iyo. Aprubahan mo, o mag-comment ka at susubukan ulit ng team. Walang makakarating sa Tapos na nang hindi ikaw ang nagpapasya.","Ilang feature na hindi mo marahil inaasahan. Pinupunan ng night watch ang column na Gagawin habang natutulog ka, at pumipili ito ng mga card na hindi nangangailangan ng sagot mo. Ipinapakita ng token counter kung gaano na ang nagamit ng mga agent ngayong araw at ngayong linggo, at sinasabihan sila ng No Token Mode na tumigil sa paggastos. Puwede kang magpadala ng mensahe sa mga kaibigan, at end-to-end encrypted ang mga pribadong mensahe. Nagsasalita ang board ng halos 120 wika, kasama ang Dutch, Flemish, pirate at Klingon. Wala ni isang sentimo ang babayaran dito, at walang nagtatangkang magbenta nito sa iyo.","Maliit at personal na proyekto ang AI-gile, hindi kumpanya. Gusto ni Rich na mabantayan ang ilang AI coding project nang hindi binubuksan ang bawat app para silipin ang mga ito, kaya gumawa sila ng board para rito ng mga agent, at ginamit nila ang board para buuin ang iba pang bahagi nito. Nasa saradong pre-alpha ito, ibig sabihin gumagana ito, kadalasan, para sa iilang kaibigan. Walang pricing page, walang newsletter at walang plano sa paglago. Kung mukha itong makakatulong, puwede kang humiling na subukan ito kapag mas nagbukas na ito."]},{"n":144,"texts":["Ang AI-gile ay kanban board para sa isang tao at maraming AI agent. Tumatakbo ito sa sarili mong computer at ganap na libre. Magdadagdag ka ng mga project, at bawat project ay magkakaroon ng lead at maliit na team. Makikipag-chat ka sa lead, medyo parang Discord, at ilalarawan mo ang isang idea; gagawin ito ng lead na mga card at plano, saka maghihintay na pindutin mo ang Go. Gagawin ng team ang mga card ayon sa priyoridad, gamit ang simpleng command line na ginawa para sa mga language model. Bago may bumalik sa iyo, susundan ng AI tester ang mga hakbang sa kopya ng app at maglalakip ng screenshot. Mapupunta sa tambak mo ang natapos na trabaho kasama ang mga nabagong file at ang diff. Aprubahan mo, o mag-iwan ka ng comment at gigising ang team at susubukan ulit. Ikaw lang ang puwedeng maglipat ng card sa Tapos na.","Isang araw kasama ang AI-gile, halos ganito. Sa gabi, mag-iiwan ka ng ilang comment: mali ang lugar ng buton na ito, dapat naka-sort ang listahang iyon, puwede bang magkaroon ng dark mode. Matutulog ka na. Babasahin ng mga agent ang mga comment, gagawin ang mga pagbabago, susubukan ang mga ito at ibabalik sa iyo. Kung maubusan ang Gagawin, pupunuin ito ng night watch mula sa backlog ng mga card na hindi nangangailangan ng sagot mo. Sa umaga, may isang maikling tambak: ilang tanong at ilang susubukan, bawat isa ay may mga hakbang na masusundan ng inaantok na tao at screenshot na gumagana ito. Magki-click ka, aaprubahan ang magaganda, at ibabalik ang iba. Ipinapakita ng token counter kung ano ang nagamit ng lahat ng ito, at nandiyan ang No Token Mode para sa mga mahigpit na linggo. Pagkatapos ay mag-aalmusal ka, na hindi pa kayang tulungan ng mga agent.","Una, kung ano ang hindi AI-gile. Hindi ito startup, hindi ito ibinebenta, at walang kumukuha ng data mo. Libreng board ito na tumatakbo sa computer mo, walang account, walang tracker at walang cookie. Ito naman ang AI-gile: isang maayos na lugar para makita ang bawat AI coding project nang sabay-sabay, may team ng mga agent na gumagawa ng mga card at ikaw ang nagpapasya. Pinagsasama nito ang magkakaugnay na card, inaayos ang magulong pamagat, at binabantayan kung nananatiling magaan ang code. Nagsasalita ito ng halos 120 wika, mula Dutch at Flemish hanggang pirate at Klingon. Puwedeng magpadala ng mensahe ang magkakaibigan sa isa't isa, pribado at naka-encrypt. Binuo ito ni Rich at ng napakaraming matiyagang agent, kadalasan sa pamamagitan ng paggamit dito mismo. Nasa saradong pre-alpha ito, kaya may gaspang pa sa ilang bahagi. Kung mukhang masaya, magtanong nang magalang at baka makapasok ka nang maaga."]}],"quips":{"1":"Isang salita. Matapang. Baka sobra pa.","3":"Tatlong salita. Mas tapat na kaysa sa karamihan ng product page.","8":"Walong salita. Mas maikli pa sa isang stand-up.","21":"Nga pala, story point ang mga haba. Siyempre naman.","55":"Limampu't limang salita. Dalawang card ang natapos habang binabasa mo iyan.","144":"Iyan ang mahaba. Walang 233. Natulog na ang mga agent."}},"timeline":{"first-idea.name":"Ang unang idea","first-idea.line":"Ang pinakaunang usapan, bago pa magkaroon ng anumang code.","first-board.name":"Unang board","first-board.line":"Board na sinusubaybayan ang sarili nitong pagbuo: mga card, column, drag and drop, mga project.","team-roles.name":"Team at mga role","team-roles.line":"Mga profile ng agent, template ng team, mga space at kung sino ang gumagawa ng ano.","install.name":"Pag-install at mga release","install.line":"Zip na kayang i-install ng kaibigan, self-update, mga channel at pag-roll back.","usage-saver.name":"Pagtitipid sa gamit","usage-saver.line":"Sukatin ang gastos ng bawat takbo, panatilihing magaan ang code, protektahan ang limit mo.","friends.name":"Mga kaibigan at pagbabahagi","friends.line":"Mga pribadong DM, ginulong relay, mga imbitasyon, mga role at pinagsasaluhang project.","languages.name":"Mga wika","languages.line":"Bawat teksto sa screen ay nasa language file, Dutch at Flemish muna.","ai-tester.name":"AI tester","ai-tester.line":"Sinusuri muna ng tester ang bawat pasa at ipinapakita ang nakita niya.","website.name":"Ang website","website.line":"Ang aigile.lol, ang teaser at ang timeline na ito.","streaming.name":"Chat at streaming","streaming.line":"Discord, Twitch, OBS, streamer mode, mga GIF at emoji.","no-ai.name":"Edisyong walang AI","no-ai.line":"Board para sa mga nagko-code nang walang AI, at mga pampublikong board.","night-watch.name":"Night watch","night-watch.line":"Isang bantay at Scrum Master ang nagpapanatili sa mga team sa gawain habang natutulog ka.","p-more.name":"Lahat ng iba pa","p-more.line":"Mas maliliit na idea na naghihintay pa ng turn nila.","p-android.name":"Telepono at Android","p-android.line":"Maabot ang board mo mula sa telepono, tapos native na Android app.","p-release.name":"Alpha at higit pa","p-release.line":"Saradong alpha, ang live na site, tapos beta.","p-languages.name":"Higit pang wika","p-languages.line":"130 wika, at immersion mode para sa mga nag-aaral.","p-engines.name":"Higit pang AI engine","p-engines.line":"Pumili ng Claude, Codex, Gemini, Copilot o Cursor para sa bawat agent.","p-pro.name":"Propesyonal na gawi","p-pro.line":"Mga risk label, merge gate, mga incident card at mga guard rail.","p-self.name":"Pag-aalaga sa iyo","p-self.line":"Tired mode, mga paalala sa self-care at 4:20.","p-servers.name":"Mga server at paglaki","p-servers.line":"Pangkalahatang setting ng server, mga role at pagpaplano para sa paglago.","p-livestream.name":"Mga dagdag sa streaming","p-livestream.line":"Twitch chat, custom na emoji at pampublikong live view."},"words":{"button":"📖 Mga teknikal na termino","h":"📖 Mga salitang ipinaliwanag","intro":"Libreng training sa simpleng wika: bawat salitang makakasalubong mo mula sa unang ideya hanggang sa serbisyong inaasahan ng mga tao, kasama ang Agile, pagbuo, pagpapanatiling ligtas nito at pagtatrabaho kasama ang AI.","search":"Maghanap ng salita…","none":"Walang salitang tumutugma.","close":"Isara","count":{"one":"{count} salita","other":"{count} salita"},"groups":[{"id":"idea","name":"💡 Ideya at discovery"},{"id":"plan","name":"🗺️ Pagpaplano ng trabaho"},{"id":"agile","name":"🔁 Mga Agile na paraan ng pagtatrabaho"},{"id":"build","name":"🛠️ Pagbuo"},{"id":"test","name":"🧪 Pagte-test at kalidad"},{"id":"change","name":"🔀 Ligtas na pagbabago"},{"id":"run","name":"🛎️ Pagpapatakbo ng service"},{"id":"sec","name":"🔒 Seguridad at privacy"},{"id":"ai","name":"🤖 Pagtatrabaho kasama ang AI"},{"id":"money","name":"💰 Pera at mga lisensya"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"Ang unang yugto ng pag-alam kung aling problema ang sulit lutasin at para kanino, bago pa may buuin.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"Isa o dalawang pangungusap na nagsasabi kung sino ang may problema, ano ito at bakit mahalaga, para iisa ang tinututukan ng lahat.","also":["mga problem statement"]},{"id":"user","g":"idea","word":"User","text":"Taong gumagamit ng ginagawa mo. Ang mga pangangailangan nila ang dahilan ng trabaho.","also":["mga user"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Sinumang may pakialam sa kalalabasan ng trabaho o naaapektuhan nito, tulad ng nagbabayad, gumagamit o sumusuporta rito.","also":["mga stakeholder"]},{"id":"persona","g":"idea","word":"Persona","text":"Kathang tao pero makatotohanan na kumakatawan sa isang uri ng user, para maitanong ng team na “madali kaya ito para kay Sam?”","also":["mga persona"]},{"id":"userresearch","g":"idea","word":"User research","text":"Pakikipag-usap at pagmamasid sa totoong tao para malaman ang kailangan nila, sa halip na manghula.","also":["user interviews","pananaliksik sa user"]},{"id":"journey","g":"idea","word":"User journey","text":"Ang mga hakbang ng isang tao para magawa ang isang bagay, mula sa unang pagkarinig hanggang matapos, kahit sa labas ng produkto mo. Kapag iginuhit mo ito, makikita kung saan siya nahihirapan.","also":["mga user journey","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Isang bagay na nakaiinis o nagpapabagal sa mga tao ngayon. Inaalis ng magagandang produkto ang mga pain point.","also":["mga pain point"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Isang bagay na pinaniniwalaan mo pero hindi mo pa nasusuri. Kapag isinulat ang mga assumption, makikita kung ano ang unang dapat subukan.","also":["mga assumption"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"Pinakamagandang hula na plano mong subukan, kasama ang inaasahang mangyayari, tulad ng “magsa-sign up ang mga tao kung libre ang unang buwan”.","also":["mga hypothesis"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Maliit at planadong pagsubok para malaman kung gumagana ang isang ideya, bago ka tumaya nang malaki.","also":["mga experiment","eksperimento"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"Mabilis at magaspang na pagsubok para makita kung puwede bang gumana ang isang ideya. Karaniwang itinatapon ito kapag nakuha na ang sagot.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"Maagang modelo ng produkto, madalas mga larawang puwedeng pindutin, para masubukan ang ideya sa mga tao bago ito buuin nang maayos.","also":["mga prototype"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"Simpleng sketch ng isang screen na nagpapakita kung saan ilalagay ang mga bagay, walang kulay at totoong nilalaman.","also":["mga wireframe"]},{"id":"mockup","g":"idea","word":"Mockup","text":"Detalyadong larawan ng magiging itsura ng isang screen, may totoong kulay at teksto, pero wala pang gumagana.","also":["mga mockup","mock-up"]},{"id":"bizcase","g":"idea","word":"Business case","text":"Ang mga dahilan para gawin ang isang project: magkano ang gastos, ano ang kikitain o matitipid, at ano ang mga panganib.","also":["mga business case"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Kung talagang mabubuo at mapapanatili ang isang bagay gamit ang oras, pera at kakayahang mayroon ka."},{"id":"outcome","g":"idea","word":"Outcome","text":"Ang pagbabagong gusto mo para sa mga tao, tulad ng mas kaunting hindi nasisipot na appointment. Mas mahalaga ito kaysa sa dami ng nabuo mo.","also":["mga outcome"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Isang bagay na ginagawa ng team, tulad ng bagong screen o ulat. Hindi ibig sabihin na nakatulong na ito sa sinuman dahil lang nagawa ito.","also":["mga output"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"Numerong nagsasabi kung nagawa ng trabaho ang layunin nito, tulad ng mas maraming taong natatapos ang order nila.","also":["mga success metric"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"Mahalagang numerong binabantayan mo para malaman kung maayos ang takbo, tulad ng bilang ng sign-up kada linggo.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"Paraan ng pagtatakda ng layunin: sinasabi ng objective kung ano ang gusto mo, at ang ilang key result ay mga numerong nagpapakitang nakarating ka na.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produkto","text":"Ang binubuo at inaalagaan para sa mga user nito, tulad ng app, website o tool.","also":["mga produkto","product"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"Maikling pahayag kung sino ang tinutulungan ng produkto at saan ito patungo sa pangmatagalan.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"Ang nagpapasya kung ano ang bubuuin at sa anong pagkakasunod-sunod, para laging nasa pinakamahalaga ang team. Sa AI-gile, ikaw iyon.","also":["PO","mga product owner"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"Ang nag-aalaga sa direksyon ng produkto: aling mga problema ang nilulutas nito, para kanino at bakit. Puwede ring ibig sabihin ng PM ay project manager, kaya tingnan kung alin.","also":["mga product manager"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"Ang nagpapanatili sa project na nasa oras at nasa budget, at sumusubaybay kung sino ang gagawa ng ano at kailan.","also":["mga project manager"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"Magaspang na plano ng darating sa susunod na mga buwan, ayon sa pagkakasunod-sunod. Direksyon ang ipinapakita nito, hindi eksaktong petsa, at nagbabago habang may natututunan.","also":["mga roadmap"]},{"id":"milestone","g":"plan","word":"Milestone","text":"Isang punto sa project na sulit markahan, tulad ng “live na ang unang bersyon” o “100 user”.","also":["mga milestone"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"Ang pinakamaliit na bersyon ng produkto na kapaki-pakinabang pa rin sa totoong tao, para maaga kang makapag-aral mula sa kanila.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Isang bagay na dapat gawin o taglayin ng natapos na produkto.","also":["mga requirement"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"Kung ano ang kasama sa trabaho at, na kasinghalaga, kung ano ang hindi.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"Kapag paunti-unting nadaragdagan ang trabaho nang walang pagsang-ayon sa dagdag na oras o gastos, kaya hindi ito natatapos.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"Isang bagay na kayang gawin ng produkto para sa mga tao, tulad ng “i-reset ang password”.","also":["mga feature"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"Malaking piraso ng trabaho na hindi kayang tapusin nang minsanan, kaya hinahati ito sa mas maliliit na card.","also":["mga epic"]},{"id":"story","g":"plan","word":"User story","text":"Maliit na piraso ng trabaho na isinulat mula sa panig ng user: “Bilang mamimili, gusto kong ma-save ang basket ko para matapos ko ito mamaya.” Nagsisimula ito ng usapan kung ano ang bubuuin.","also":["mga user story"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"Ang mga tsek na dapat maipasa ng isang card para ituring na tapos, napagkasunduan bago magsimula ang trabaho, tulad ng “nandoon pa rin ang basket pagkatapos kong mag-log out at mag-log in ulit”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"Isang gawaing dapat tapusin, madalas isang maliit na hakbang ng mas malaking story.","also":["mga task"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Ibang salita para sa card: isang piraso ng trabaho o isang hiling, sinusubaybayan mula simula hanggang katapusan.","also":["mga ticket"]},{"id":"priority","g":"plan","word":"Priority","text":"Gaano kahalaga o kaapura ang isang bagay kumpara sa lahat ng iba pa, para mauna ang pinakamahalagang trabaho.","also":["mga priority","prayoridad"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritization","text":"Pagsusunod-sunod ng trabaho ayon sa halaga. Isang karaniwang paraan ang MoSCoW: Must have, Should have, Could have, Won’t have sa pagkakataong ito.","also":["prioritizing","prioritize","MoSCoW","pag-prioritize"]},{"id":"estimate","g":"plan","word":"Estimate","text":"Pinakamagandang hula kung gaano kalaki o katagal ang isang trabaho. Hula ito, hindi pangako.","also":["mga estimate","estimation","pagtataya"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"Paraan ng paghula sa laki ng trabaho sa pamamagitan ng paghahambing ng mga card sa isa’t isa (“mga dalawang beses na mas malaki kaysa roon”) sa halip na oras. Hindi ito panukat para ihambing ang mga team.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Paghula sa laki ng trabaho bilang S, M, L o XL. Mabilis ito at sapat na para sa maagang pagpaplano.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"Larong pang-estimate: sabay-sabay na ipinapakita ng lahat ang card ng laki, tapos ipinapaliwanag ng may pinakamataas at pinakamababa kung bakit.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"Kapag hindi makapagsimula o makatapos ang isang trabaho hangga’t hindi natatapos ang isa pa.","also":["mga dependency"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anumang pumipigil sa pag-usad ng trabaho ngayon, tulad ng sagot na wala pa o sirang tool.","also":["mga blocker"]},{"id":"deadline","g":"plan","word":"Deadline","text":"Ang petsang dapat matapos ang isang bagay.","also":["mga deadline"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Konkretong bagay na nagagawa at naiaabot ng trabaho, tulad ng gumaganang pahina o ulat.","also":["mga deliverable"]},{"id":"forecast","g":"plan","word":"Forecast","text":"Hula sa malamang na mangyari, tulad ng kung kailan matatapos ang trabaho, batay sa alam mo sa ngayon.","also":["mga forecast"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anumang sinusukat at sinusubaybayan mo sa paglipas ng panahon, tulad ng dami ng bumisita sa pahina o gaano katagal ayusin ang isang sira.","also":["mga metric"]},{"id":"feedback","g":"plan","word":"Feedback","text":"Ang sinasabi ng mga tao tungkol sa gawa mo, mabuti man o masama. Ang maaga at madalas na pagkuha nito ang puso ng Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ang listahan ng paghihintay ng mga ideya at trabahong hindi pa naisasama sa plano, na nasa itaas ang pinakamahalaga. Walang gagawin doon hangga’t hindi ito lumilipat sa To do."},{"id":"sprint","g":"agile","word":"Sprint","text":"Maikli at takdang yugto ng trabaho (madalas isa o dalawang linggo, hindi hihigit sa isang buwan) na may layunin at napagkasunduang set ng mga card na tatapusin.","also":["sprint","mga sprint"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Mabilis na araw-araw na check-in: ano ang ginawa ng bawat miyembro ng team, ano ang susunod na gagawin, at ano ang humaharang. Sa Scrum, tinatawag itong daily scrum.","also":["standup","stand-ups","daily scrum","daily stand-up"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Paraan ng pagtatrabaho kung saan lumilipat ang mga card sa mga column ng board (tulad ng To do, In progress, Done) at nililimitahan ng team kung gaano karami ang sabay na ginagawa, para tuloy-tuloy ang daloy ng trabaho."},{"id":"wip","g":"agile","word":"WIP limit","text":"Ang WIP ay maikli para sa work in progress. Ang WIP limit ay ang pinakamaraming card na dapat hawakan ng isang column nang sabay, para tapusin muna ng team ang mga bagay bago magsimula ng iba.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definition of Done","text":"Ang maikling checklist ng team kung ano ang ibig sabihin ng “tapos”, gaya ng na-test at naipaliwanag, bago iabot sa iyo ang isang card. Ang kakambal nito, ang Definition of Ready, ang nagsasabi kung kailan malinaw na ang card para simulan.","also":["Definition of Ready","DoD","DoR"]},{"id":"retro","g":"agile","word":"Retro","text":"Regular na pagbabalik-tanaw sa paraan ng pagtatrabaho ng team, para pagkasunduan ang isa o dalawang bagay na gagawing mas mahusay sa susunod. Maikli para sa retrospective. Sa AI-gile, nagmumungkahi ang retro ng pagbabago sa paraan ng pagtatrabaho ng team, at sasabihin mong Go o Not yet.","also":["retros","retrospective","retrospectives"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Tulong-tulong ang lahat: maraming tao ang iniiwan muna ang ibang trabaho para sabay na ayusin ang iisang apurahang bagay hanggang maayos. Sa AI-gile, tumutulong ang bawat team sa iisang project, at naghihintay muna ang ibang project.","also":["swarming","i-swarm"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Sa Scrum, ang taong tumutulong sa team na magtrabaho nang maayos: inaalis ang humaharang sa kanila, pinananatiling nasa tamang landas ang mga pulong at tinuturuan ang mabubuting gawi, nang hindi nag-uutos kaninuman. Sa AI-gile, nakikita ng Lead Scrum Master ang mga nakabarang card, kinakalabit ang mga team at pinaaalalahanan ka sa mga naghihintay, sa lahat ng project.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"Paraan ng pagtatrabaho nang paunti-unti: bumuo ng kaunti, ipakita agad ang totoong resulta, matuto sa sinasabi ng mga tao at baguhin ang plano habang tumatakbo, sa halip na planuhin ang lahat sa simula.","also":["Agile development","agile na paraan ng pagtatrabaho"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"Maikling pahayag na isinulat noong 2001 ng mga gumagawa ng software. Inuuna nito ang mga tao, gumaganang resulta, malapit na pakikipagtulungan sa customer at pagtugon sa pagbabago kaysa sa mabibigat na plano at papeles.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"Ang mas lumang paraan ng pagtatrabaho: planuhin ang lahat, tapos buuin lahat, tapos i-test lahat, sunod-sunod na yugto. Mahirap at magastos magbago kapag huli na.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"Isang ikot ng pagbuo ng isang bagay, pagsusuri at pagpapabuti nito. Sunod-sunod na ganitong ikot ang Agile na trabaho, at isang uri nito ang sprint.","also":["mga iteration"]},{"id":"increment","g":"agile","word":"Increment","text":"Bagong gumaganang piraso na idinaragdag sa produkto sa isang sprint o ikot ng trabaho, at tugma sa dati nang nandoon.","also":["mga increment"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Sikat na Agile na paraan ng pagtatrabaho: maliit na team ang gumagawa sa maiikling sprint tungo sa isang layunin, na may takdang mga role at ilang regular na pulong para magplano, sumuri at mag-improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"Ang maliit na grupong gumagawa ng trabaho sa Scrum: isang product owner, isang Scrum Master at ang mga developer.","also":["mga Scrum team"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"Ang mga regular na pulong sa Scrum: sprint planning, daily scrum, sprint review at retro. Maraming tao ang tumatawag sa mga ito na ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"Ang pulong sa simula ng sprint kung saan nagkakasundo ang team kung bakit mahalaga ang sprint, aling mga card ang kukunin at paano magsisimula.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"Isang pangungusap na nagsasabi kung para saan ang sprint. Puwedeng magbago ang maliliit na gawain habang tumatakbo, basta natutugunan ang layunin.","also":["mga sprint goal"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"Ang mga card na napili para sa kasalukuyang sprint, kasama ang plano ng team kung paano gagawin ang mga ito.","also":["mga sprint backlog"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"Ang buong nakaayos na listahan ng lahat ng maaaring buuin para sa produkto, pinakamahalaga sa itaas. Patuloy itong nagbabago habang may natututunan.","also":["mga product backlog"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"Ang mas malaking resultang tinutungo ng produkto, na tumutulong sa team na piliin ang susunod na gagawin.","also":["mga product goal"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regular na pagdaan sa backlog para ayusin, hatiin, pagsunud-sunurin at dagdagan ng detalye ang mga card, para handa na silang kunin. Tinatawag ding backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"Pulong sa pagtatapos ng sprint kung saan ipinapakita ng team ang natapos nito at pinakikinggan ang saloobin ng mga tao, para magpasya kung ano ang susunod.","also":["mga sprint review"]},{"id":"demo","g":"agile","word":"Demo","text":"Pagpapakita ng natapos na trabaho habang gumagana, live, sa mga humiling nito.","also":["mga demo"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"Takdang haba ng oras para sa isang bagay. Kapag naubos ito, humihinto ka, kahit hindi pa tapos ang lahat.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"Gaano karaming trabaho ang karaniwang natatapos ng team sa isang sprint, ginagamit para planuhin kung gaano karami ang kukunin sa susunod. Hindi ito marka kung gaano kasipag ang mga tao.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"Gaano karaming trabaho ang kayang kunin ng team sa isang panahon, matapos ibawas ang mga bakasyon at iba pang gawain.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"Tsart ng natitirang trabaho sa sprint na bumababa araw-araw. Kapag patag ang linya, may nakabara.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"Tsart ng natapos na trabahong tumataas sa paglipas ng panahon, katabi ng kabuuang plano, para makita kung kailan mo ito maaabot.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"Ang board mismo: isang column para sa bawat yugto ng trabaho, na may mga card na lumilipat sa mga ito.","also":["mga Kanban board"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"Paraan ng pagtatrabaho kung saan magsisimula lang ang bagong trabaho kapag may espasyo na ang isang tao para kunin ito, sa halip na ipilit sa taong puno na ang plato.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"Gaano kakinis ang paglipat ng trabaho sa board. Ang magandang flow ay nangangahulugang patuloy na gumagalaw ang mga card at hindi nagpapatung-patong.","also":["flow of work","daloy ng trabaho"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"Gaano katagal mula nang humingi ang isang tao hanggang sa matapos ito.","also":["mga lead time"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"Gaano katagal ang isang card mula nang talagang simulan ang trabaho hanggang matapos ito.","also":["mga cycle time"]},{"id":"throughput","g":"agile","word":"Throughput","text":"Ilang card ang natatapos sa isang linggo, o sa anumang takdang panahon.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"Ang iisang yugto kung saan nagpapatung-patong ang trabaho at nagpapabagal sa lahat ng nasa likod nito, tulad ng makitid na leeg ng bote.","also":["mga bottleneck"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"Hilera sa kabuuan ng board na nagpapangkat ng mga card na magkauri, tulad ng mga apurahang trabaho o mga card ng isang team.","also":["mga swimlane","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"Paraan ng pagtatrabaho na nag-aalis ng aksaya (anumang hindi nakatutulong sa customer) at pinananatiling umaagos ang trabaho."},{"id":"waste","g":"agile","word":"Waste (aksaya)","text":"Sa Lean, anumang gumagamit ng pagod pero hindi nakatutulong sa customer, tulad ng paghihintay, pag-uulit ng gawa o pagbuo ng mga bagay na walang gumagamit.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Unti-unting paghusay palagi sa pamamagitan ng maliliit at regular na pagbabago, tapos sinusuri kung nakatulong ang mga ito. Isang paraan nito ang mga retro. Tinatawag ding kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organizing team","text":"Team na nagpapasya mismo kung paano gagawin ang trabaho, sa halip na sabihan nang hakbang-hakbang.","also":["self-organizing","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"Team na nasa kanya na ang lahat ng kakayahang kailangan para tapusin ang trabaho nang mag-isa, tulad ng disenyo, pagbuo at pagsubok.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"Maikli at may takdang oras na pananaliksik para masagot ang isang tanong bago mangako sa totoong trabaho.","also":["mga spike"]},{"id":"rework","g":"agile","word":"Rework","text":"Pag-uulit ng trabaho dahil hindi tama sa unang beses.","also":["reworked","pag-uulit ng gawa"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Mga paraan ng paggamit ng Agile sa maraming team sa isang malaking organisasyon. Ang SAFe (Scaled Agile Framework) ay isang kilalang halimbawa.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Ang folder ng project na may code at buong kasaysayan ng mga commit. Puwede itong nasa computer mo, sa GitHub, o pareho.","also":["repo","repository"]},{"id":"branch","g":"build","word":"Branch","text":"Hiwalay na linya ng trabaho sa code, para makapagbago nang hindi ginagalaw ang pangunahing bersyon.","also":["branch","mga branch"]},{"id":"commit","g":"build","word":"Commit","text":"Naka-save na snapshot ng code, na may maikling note kung ano ang nagbago. Puwede kang laging bumalik sa isa.","also":["commit","mga commit"]},{"id":"push","g":"build","word":"Push","text":"Pagpapadala ng mga naka-save mong snapshot (commit) mula sa computer na ito patungo sa pinagsasaluhang kopya online, tulad ng GitHub, para may backup at makuha ng iba."},{"id":"merge","g":"build","word":"Merge","text":"Pagsasama ng mga pagbabago mula sa isang branch papunta sa isa pa, kadalasan pabalik sa pangunahing bersyon."},{"id":"pr","g":"build","word":"Pull request","text":"Paghiling na suriin at isama sa pangunahing bersyon ang mga pagbabago ng isang branch. Tinatawag itong merge request ng ibang site.","also":["PR","PRs","merge request"]},{"id":"refactor","g":"build","word":"Refactor","text":"Pag-aayos ng code nang hindi binabago ang ginagawa nito: mas maliliit na file, mas malilinaw na pangalan, mas kaunting pag-uulit."},{"id":"bug","g":"build","word":"Bug","text":"Isang bagay na hindi gumagana nang tama.","also":["bug","mga bug"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Pangalawang pares ng mata: may ibang tao maliban sa may-akda na sumusuri sa trabaho bago ito umabot sa iyo, para mas kaunting pagkakamali ang makalusot. Sa AI-gile, ibang AI ang sumusuri sa bawat card.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"Ang mga nakasulat na tagubilin na nagsasabi sa computer kung ano ang gagawin. Tinatawag ding source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"Wika para sa pagsulat ng code, tulad ng JavaScript, Python o Java. Iba-iba ang angkop sa iba’t ibang trabaho.","also":["mga programming language"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Taong sumusulat at nagbabago ng code. Tinatawag ding programmer o software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Mga programang tumatakbo sa computer at telepono, kaiba sa mismong mga makina (ang hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Maikli para sa application: programang ginagamit ng mga tao para magawa ang isang bagay, sa telepono, computer o web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"App na tumatakbo sa web browser, kaya walang kailangang i-install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"Ang bahagi ng app na nakikita at pinipindot mo: ang mga screen, button at salita, madalas sa browser mo.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"Ang bahaging nasa likod ng eksena ng app na nag-iingat ng data at gumagawa ng trabaho kapag may pinindot ka, tulad ng pagsuri sa password mo.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Pagtatrabaho sa parehong front end at back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"Ang nakikita at ginagamit ng tao sa screen: layout, mga button, menu at teksto.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"Kung ano ang pakiramdam ng paggamit ng isang bagay: madali, malinaw at kaaya-aya, o nakalilito at mabagal.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Paggawa ng mga bagay na magagamit ng lahat, kasama ang mga hindi nakakakita nang maayos, hindi makagamit ng mouse o gumagamit ng screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Paggawa ng mga pahinang umaangkop at maayos gumana sa anumang laki ng screen, mula telepono hanggang malaking monitor."},{"id":"designsys","g":"build","word":"Design system","text":"Pinagsasaluhang kit ng mga kulay, font, button at patakaran, para pareho ang itsura at kilos ng bawat screen.","also":["mga design system"]},{"id":"architecture","g":"build","word":"Architecture","text":"Ang pangkalahatang hugis ng isang sistema: ano ang mga pangunahing bahagi at paano sila nag-uusap."},{"id":"database","g":"build","word":"Database (DB)","text":"Maayos na imbakan ng impormasyon, parang napakalakas na spreadsheet na kayang basahin at baguhin ng app.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"Ang ayos ng isang database: anong mga table ng impormasyon ang mayroon at ano ang laman ng bawat isa.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Maikli para sa structured query language: ang wikang ginagamit para humingi ng impormasyon sa maraming database o baguhin ito.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Impormasyong iniingatan ng computer, tulad ng mga pangalan, order o setting.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Computer na laging bukas at sumasagot sa mga hiling ng ibang computer, tulad ng pagpapadala ng web page kapag binisita mo ito.","also":["mga server"]},{"id":"client","g":"build","word":"Client","text":"Ang panig na humihingi ng isang bagay, kadalasan ang browser o app mo, na kumakausap sa server. Sa negosyo, ibig sabihin din nito ay customer.","also":["mga client"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Maikli para sa application programming interface: nakatakdang menu ng mga hiling na magagawa ng isang programa sa isa pa, tulad ng paghingi sa weather service ng forecast ngayon.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"Isang item sa menu ng API: web address na puwedeng tawagan ng programa para kumuha o magpadala ng isang bagay.","also":["mga endpoint"]},{"id":"integration","g":"build","word":"Integration","text":"Pagkokonekta ng dalawang sistema para magtulungan, tulad ng pagpapadala ng shop mo ng mga order sa accounting software mo.","also":["mga integration"]},{"id":"webhook","g":"build","word":"Webhook","text":"Mensaheng kusang ipinapadala ng isang sistema sa isa pa sa sandaling may mangyari, tulad ng “natanggap na ang bayad”.","also":["mga webhook"]},{"id":"library","g":"build","word":"Library","text":"Handang code na isinulat ng iba na puwede mong gamitin ulit sa halip na isulat mismo.","also":["mga library"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Handang balangkas para sa pagbuo ng app na nagpapasya sa malaking bahagi ng ayos ng code, parang frame ng bahay na pupunuan mo.","also":["mga framework"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"Kahon ng mga tool, code at halimbawa para sa pagbuo ng software para sa isang platform o serbisyo.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"Library o tool na kailangan ng code mo para gumana. Mahalaga para sa seguridad ang pagpapanatili sa mga itong updated.","also":["mga software dependency"]},{"id":"package","g":"build","word":"Package","text":"Bungkos ng handang code na puwede mong i-install at gamitin sa isang project.","also":["mga package"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"Tool na kumukuha at nag-a-update ng mga package na kailangan ng code mo. Karaniwan ang npm.","also":["mga package manager","npm"]},{"id":"git","g":"build","word":"Git","text":"Ang pinakamalawak na ginagamit na tool para itago ang kasaysayan ng mga pagbabago sa code, bilang mga commit at branch."},{"id":"github","g":"build","word":"GitHub","text":"Website na nag-iingat ng mga Git repo online, para makapagbahagi ng code, makapag-review ng pagbabago at makasubaybay ng trabaho ang mga team."},{"id":"vcs","g":"build","word":"Version control","text":"Pag-iingat ng buong kasaysayan ng bawat pagbabago sa mga file, para makita kung sino ang nagbago ng ano at makabalik kung kailangan. Ginagawa ito ng Git.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Paggawa ng sarili mong buong kopya ng repo, kasama ang kasaysayan nito, sa computer mo.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Pagkuha ng pinakabagong mga commit mula sa pinagsasaluhang kopya (tulad ng GitHub) papunta sa computer mo. Kabaligtaran ng push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"Ang opisyal na bersyon ng code na pinagmumulan ng lahat, madalas tinatawag na main o master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"Kapag dalawang pagbabago ang humipo sa parehong mga linya sa magkaibang paraan, kaya hindi ito mapagsama ng computer at tao ang dapat pumili.","also":["mga merge conflict"]},{"id":"diff","g":"build","word":"Diff","text":"Tanawing nagpapakita nang eksakto kung ano ang nagbago sa pagitan ng dalawang bersyon: mga linyang idinagdag at mga linyang inalis.","also":["mga diff"]},{"id":"fork","g":"build","word":"Fork","text":"Sarili mong kopya ng repo ng iba, na puwede mong baguhin nang hindi naaapektuhan ang kanila.","also":["mga fork","forked"]},{"id":"script","g":"build","word":"Script","text":"Maikling programang gumagawa ng isang trabaho nang mag-isa, tulad ng pag-aayos ng mga file o pagpapatakbo ng app.","also":["mga script"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Pag-convert ng code sa isang bagay na handang patakbuhin, o ang mismong resultang handa nang patakbuhin.","also":["mga build"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Pagsasalin ng code na isinulat ng tao sa anyong direktang mapapatakbo ng computer.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"Text window kung saan nagta-type ka ng mga tagubilin sa computer sa halip na magpindot. Tinatawag ding terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"Ang mga setting na kumokontrol sa kilos ng software, hiwalay sa code para madaling baguhin.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"Setting na ibinibigay sa programa sa pagsisimula nito, madalas para sa mga address o password para hindi na isulat ang mga ito sa code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Paghahanap kung bakit hindi gumagana ang isang bagay, at pag-aayos nito.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Dalawang tao (o isang tao at isang AI) na magkasamang nagtatrabaho sa iisang code, isa ang nagta-type at isa ang sumusuri.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Mga nakasulat na paliwanag kung paano gumagana ang isang bagay o paano ito gagamitin.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Ang unang file na babasahin sa isang repo: ano ang project at paano ito patatakbuhin.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"Lumang sistemang ginagamit pa rin na mahirap baguhin, madalas dahil kaunti na lang ang nakakaunawa rito.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Mga shortcut na nakatitipid ng oras ngayon pero nagpapabagal ng mga susunod na pagbabago, parang utang na lumalaki ang interes. Binabayaran ito ng refactoring.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Pagsusuri kung gumagana ang isang bagay ayon sa dapat. May mga test na kusang pinatatakbo ng computer sa bawat pagbabago ng code; ang iba ay ikaw mismo ang sumusubok sa natapos na card bago mo tanggapin.","also":["test","mga test"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Maikli para sa quality assurance: lahat ng ginagawa para matiyak na tama ang trabaho bago mag-live. Sa AI-gile, ito ang mga awtomatikong tsek: kapag pula ang QA, may pumalya, at hindi ito puwedeng mag-live hangga’t hindi naaayos.","also":["quality checks","quality assurance","pagsusuri ng kalidad"]},{"id":"testpile","g":"test","word":"Test pile","text":"Ang mga tapos na card na naghihintay na subukan mo, isa-isa. Tanggapin ang isa o ibalik ito na may note, at lalabas ang susunod.","also":["test piles"]},{"id":"autotest","g":"test","word":"Automated test","text":"Tsek na kusang pinatatakbo ng computer sa bawat pagbabago ng code, para maagang mahuli ang mga pagkakamali.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"Taong sumusubok ng trabaho nang mano-mano para makita kung kumikilos ito gaya ng dapat.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"Maliit na awtomatikong tsek ng isang munting piraso ng code nang mag-isa.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"Tsek na maayos na nagtutulungan ang ilang bahagi, hindi lang isa-isa.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"Test na kumikilos na parang totoong user mula simula hanggang wakas, tulad ng pag-sign up, pagbili at pagbayad.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"Ang mga humiling ng trabaho ang mismong sumusubok nito at nagsasabi kung ginagawa nito ang kailangan nila. Ang test pile ng AI-gile ang bersyon nito.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Isang bagay na dating gumagana pero nasira pagkatapos ng pagbabago. Sinusuri ng mga regression test na gumagana pa rin ang mga luma.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"Napakabilis na tsek kung gumagana man lang ang mga pangunahing bagay, halimbawa kaagad pagkatapos mag-live ng pagbabago. Kapag pumalya, huminto at tingnan.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Malayang pagsubok sa produkto at pagkalikot dito sa iba’t ibang paraan, para makahanap ng problemang makakaligtaan ng mga planadong tsek.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"Isang nakasulat na senaryong susubukan: ang mga hakbang, at kung ano ang dapat mangyari.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"Gaano karami sa code ang sinusuri ng mga awtomatikong test. Kadalasan, mas ligtas ang mas marami, pero hindi pa rin nito napatutunayang maayos ang takbo ng code dahil lang mataas ang coverage.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Kathang halimbawang impormasyon na ginagamit habang nagte-test, para walang malantad na pribadong detalye ng totoong tao.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"Kakaibang sitwasyon sa mga hangganan, tulad ng walang laman na form o pangalang may apostrophe, kung saan madalas masira ang mga bagay.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"Ang normal na daan kung saan maayos ang lahat. Sinusubukan din ng mahusay na pagte-test ang mga unhappy path, kung saan may nagkakamali."},{"id":"perftest","g":"test","word":"Performance testing","text":"Pagsusuri kung gaano kabilis ang isang bagay at kung gaano ito kahusay humarap sa bigat.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Pagsusuri kung paano hinaharap ng sistema ang sabay-sabay na paggamit ng napakaraming tao.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Paghahanap ng mga kahinaang magpapahintulot sa sinuman na abusuhin ang sistema o makita ang hindi dapat makita.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Pagsusuring magagamit ng mga taong may iba’t ibang kakayahan ang produkto, kasama ang paggamit ng screen reader o keyboard lang.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Awtomatikong tsek na nakakakita ng malamang na pagkakamali at magulong istilo sa code, parang spelling checker para sa mga programa.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Pagsusuri ng code para sa mga problema sa pamamagitan ng awtomatikong pagbasa rito, nang hindi ito pinatatakbo.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"Test na minsan pumapasa at minsan pumapalya nang walang malinaw na dahilan, kaya hindi lubos na mapagkakatiwalaan.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Sadyang pagpapangyari ulit ng bug sa pamamagitan ng parehong mga hakbang, para mapag-aralan at maayos. Ang pagsulat ng mga hakbang na iyon ang pinakamakatutulong na bahagi ng ulat ng bug.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"Gaano kalala ang epekto ng problema, mula sa maliit na abala hanggang sa paghinto ng lahat.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Pagkopya ng bagong bersyon ng software sa mga computer na nagpapatakbo nito, tulad ng test copy o live na serbisyo."},{"id":"release","g":"change","word":"Release","text":"Isang bungkos ng tapos na trabaho na may pangalan at sabay-sabay na nagla-live, kasama ang maikling notes kung ano ang nagbago. Ang 🚀 Releases ang sumusulat ng notes mula sa mga tapos na card.","also":["releases","mga release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Pagbalik sa huling bersyong gumana kapag nagdudulot ng gulo ang bago. Sa AI-gile, kinokolekta ng Roll back ang mga hakbang sa pag-undo na nakasulat sa bawat pagbabago sa iisang checklist.","also":["roll back","i-rollback","na-rollback"]},{"id":"live","g":"change","word":"Live","text":"Ang totoong bersyon na ginagamit ng mga tao, hindi ang kopya para sa pagsubok. Tinatawag din ito ng mga developer na production.","also":["production","naka-live","mag-live"],"noTip":1},{"id":"change","g":"change","word":"Pagbabago","text":"Isang planadong pagbabago sa bagay na inaasahan ng mga tao, na isinusulat muna: ano, bakit, ang panganib, kailan, at paano ito ia-undo. Magsimula ng isa sa 🔀 Mag-raise ng pagbabago.","also":["mga pagbabago","change","change request","change requests"],"noTip":1},{"id":"risk","g":"change","word":"Panganib","text":"Isang bagay na puwedeng magkamali, na may score batay sa kung gaano ito kalamang at gaano kalala. Itinatabi ng ⚠️ Mga panganib ang lahat sa iisang listahan, pinakamataas na score muna, bawat isa may petsa kung kailan titingnan ulit.","also":["mga panganib","risk","risks","risk register"]},{"id":"chgwin","g":"change","word":"Change window","text":"Ang mga oras kung kailan puwedeng mag-live ang mga pagbabago, gaya ng tahimik na Martes ng gabi. Sa labas ng window, hindi matatapos ang isang change card, maliban kung emergency.","also":["mga change window","change windows"]},{"id":"gonogo","g":"change","word":"Go / No go","text":"Huling tsek bago mag-live ang pagbabago: sinasabi ng bawat kailangang mag-apruba na Go o No go. Itutuloy lang ito kapag Go ang sagot ng lahat.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approval","text":"Paghihintay ng oo bago magsimula ang trabaho. Ang card na ginawa ng isang kaibigan, o isang pagbabago, ay naghihintay sa ✅ Mga approval hanggang i-approve o i-decline mo ito.","also":["mga approval","approvals","pag-apruba"]},{"id":"quiettime","g":"change","word":"Tahimik na oras","text":"Yugto ng oras, tulad ng habang may live stream, demo o magdamag, kung kailan walang nagla-live. Patuloy sa pagtatrabaho at pagte-test ang mga team, pero naghihintay ang pag-live hanggang matapos ito. Sa ibang lugar, tinatawag itong change freeze.","also":["mga tahimik na oras","quiet time","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Paraan ng pagtatrabaho kung saan iisang team ang mga gumagawa ng software at ang mga nagpapatakbo nito, na maraming automation, para madalas at ligtas ang pag-live ng mga pagbabago."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration at delivery)","text":"Madalas na pinagsasama sa pangunahing bersyon ang mga pagbabago ng lahat at awtomatikong sinusuri sa bawat pagkakataon (continuous integration), kaya laging handa ang software na mag-live sa isang pindot (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"Isang hakbang pa mula sa continuous delivery: bawat pagbabagong pumasa sa mga tsek ay kusang nagla-live, walang pipindutin.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"Ang awtomatikong serye ng mga hakbang na dinaraanan ng pagbabago patungong live, tulad ng build, test, tapos deploy.","also":["mga pipeline"]},{"id":"environment","g":"change","word":"Environment","text":"Isang hiwalay na kopya ng sistema para sa isang layunin, tulad ng isa para sa pagbuo, isa para sa pag-test at ang live.","also":["mga environment"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"Ang kopyang pinagtatrabahuhan ng developer, madalas sa sarili niyang computer, kung saan walang masasaktan kapag may nasira.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"Hiwalay na kopya ng sistema na pang-test lang, para hindi magalaw ang totoong serbisyo.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"Huling kopyang ginawang kapareho ng live, para sa huling tsek bago mag-live ang pagbabago.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"Ang file o bungkos na nabubuo ng isang build, handa nang itabi, suriin o i-live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"Apurahang ayos na mabilis na ini-live, labas sa karaniwang plano, dahil may mahalagang nasira.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"Maliit na update na nag-aayos ng bug o nagsasara ng butas sa seguridad. Mahalagang mabilis maipatupad ang mga security patch.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"Label na tulad ng 2.4.1 na nagsasabi kung aling release ang mayroon ka. Madalas nagbabago ang unang numero para sa malalaking pagbabago at ang huli para sa maliliit na ayos.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"Maikli at simpleng listahan ng nagbago sa isang release, para sa mga gumagamit nito, kasama ang mga ayos at kilalang limitasyon. Tinatawag ding changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"Switch na on at off para sa isang feature, para puwedeng i-live nang nakatago ang bagong gawa at buksan (o isara ulit) nang walang bagong release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Pag-aayos ng masamang release sa pamamagitan ng mabilis na paglabas ng bago at naitamang bersyon sa halip na bumalik sa luma.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Pag-live muna ng pagbabago para sa maliit na grupo, at para sa lahat lang kapag mukhang maayos. Hango ito sa mga canary na dinadala ng mga minero sa ilalim ng lupa bilang maagang babala.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Pagpapanatili ng dalawang kopya ng live na sistema at paglilipat ng mga tao sa bago nang sabay-sabay, para makabalik agad kapag pumalpak.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Pag-live ng bagong bersyon nang hindi kailanman humihinto ang serbisyo para sa mga user nito.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Pagtulong na magtagumpay ang mga pagbabago: pagtimbang sa panganib, pagkuha ng tamang pag-apruba at pagpili ng magandang oras. Tinatawag ding change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"Grupong sumusuri sa mahahalagang pagbabago at sumasang-ayon kung puwede at kailan sila itutuloy.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"Pagbabagong mababa ang panganib na ginagawa sa parehong subok nang paraan sa bawat pagkakataon, kaya naaprubahan na nang maaga.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"Pagbabagong kailangang suriin at aprubahan bago ituloy.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"Pagbabagong kailangang gawin agad para ayusin o pigilan ang malubhang problema, na may mas mabilis na pag-apruba.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Pagpapagawa sa computer ng paulit-ulit na trabaho nang mag-isa, para mas mabilis at pareho ang paraan sa bawat pagkakataon.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"Ang mga makina, network at serbisyong pinatatakbuhan ng software.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Paglalarawan sa mga server at setting mo sa mga file na kasama ng code, para muling mabuo nang eksaktong pareho sa bawat pagkakataon.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Pag-upa ng mga computer, imbakan at serbisyo mula sa malaking provider sa internet, sa halip na ikaw mismo ang may-ari ng mga makina.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"Kumpanyang umuupa ng computing sa internet, tulad ng Amazon Web Services (AWS), Microsoft Azure o Google Cloud.","also":["mga cloud provider"]},{"id":"hosting","g":"change","word":"Hosting","text":"Kung saan nakatira at tumatakbo ang app o website mo para maabot ng mga tao, kadalasang inuupahan sa isang kumpanya."},{"id":"domain","g":"change","word":"Domain name","text":"Ang web address na tina-type ng mga tao, tulad ng example.com. Taun-taon mo itong inuupahan, kaya kailangang i-renew.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Maikli para sa domain name system: ang address book ng internet, na nagpapalit ng pangalang tulad ng example.com sa address ng tamang computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"Selyadong pakete na may app at lahat ng kailangan nito, para pare-pareho ang takbo sa anumang computer. Ang Docker ang pinakakilalang tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"Kunwaring computer na tumatakbo sa loob ng totoo, para ang isang malaking makina ay magmukhang marami.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Pagpapatakbo ng code nang hindi ka mismo nag-aalaga ng anumang server: pinatatakbo ito ng provider kapag kailangan at babayaran mo lang ang nagamit mo."},{"id":"lb","g":"change","word":"Load balancer","text":"Bagay na namamahagi ng mga bisita sa ilang server, para walang iisang server na matabunan.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"Madaling-abot na imbakan ng mga kamakailang resulta na itinatabi sa malapit, para hindi na kailangang kunin o kalkulahin ulit ang parehong bagay. Kapag nilinis ito, minsan naaayos ang mga pahinang mukhang luma.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"Pandaigdigang hanay ng mga server na may kopya ng mga pahina at larawan mo malapit sa mga bisita, para mabilis mag-load.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Paglilipat ng data o sistema mula sa luma tungo sa bagong ayos, o maingat na pagbabago sa ayos ng isang database.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Service","text":"Isang bagay na binuo mo na inaasahan ng mga tao, gaya ng website o app, na inaalagaan para patuloy na gumana. I-tick ang “Ang project na ito ay isang service” at sabihin kung ano ang inaalok nito, sino ang gumagamit at sino ang on-call.","also":["services","mga service","serbisyo"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"Gaano karaming oras gumagana ang serbisyo, kadalasang bilang porsiyento. Kahit 99.9%, puwede pa ring patay ito nang mga 43 minuto kada buwan.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime check","text":"Isang awtomatikong check, bawat ilang minuto, na sumasagot pa ang service mo. Kapag pumalya ito nang ilang beses na sunod-sunod, kusang magbubukas ang AI-gile ng incident card.","also":["uptime checks"]},{"id":"statuspage","g":"run","word":"Status page","text":"Isang pampublikong page na nagpapakita kung gumagana ang isang service (berde, orange o pula) kasama ang pinakabagong update, para ang mga gumagamit ay makatingin na lang sa halip na magtanong.","also":["status pages"]},{"id":"desk","g":"run","word":"Service desk","text":"Dito pumapasok ang mga tanong at report mula sa mga taong gumagamit ng service mo. Inuuri ng AI-gile ang bawat isa bilang request, incident o idea, at sinasabi nito kapag mukhang naireport na dati.","also":["service desks","desk","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"May humihingi ng karaniwang bagay, gaya ng bagong account o kaunting tulong, sa halip na mag-report na may sira. Naghihintay ito ng turno nito; nauuna ang incident.","also":["service requests"]},{"id":"incident","g":"run","word":"Incident","text":"Isang bagay na sira o hindi maayos na gumagana ngayon para sa mga gumagamit nito, tulad ng website na patay o napakabagal. Nauuna sa pila ang 🔥 incident card: ang pagpapagana ulit dito ang una.","also":["incidents","mga incident","insidente"]},{"id":"major","g":"run","word":"Major incident","text":"Isang malaking incident: maraming taong apektado, o nanganganib ang pera o data. Isang button ang naglalagay sa lahat ng team dito (swarm), gumigising sa kung sino ang on-call, at humihingi ng status update bawat 30 minuto.","also":["major incidents"]},{"id":"oncall","g":"run","word":"On call","text":"Ikaw ang sasagot kapag may nasira, kahit gabi. Bawat service ay may on-call na miyembro ng team na unang ginigising para sa mga incident nito.","also":["on-call"]},{"id":"replyby","g":"run","word":"Reply-by time","text":"Kung gaano katagal puwedeng maghintay ang isang card ng unang sagot, halimbawa isang oras para sa incident. Pagkatapos noon, nagkakaroon ito ng pulang orasan, para walang tahimik na makalimutan. Tinatawag din itong response target.","also":["reply-by times","response target","response targets"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Isang maikling pagbabalik-tanaw pagkatapos ng incident: ano ang nangyari, ano ang nakatulong at ano ang babaguhin, nang walang sinisisi. Hindi maisasara ang isang incident nang wala nito.","also":["post-mortems","postmortem","post-incident review"]},{"id":"problem","g":"run","word":"Problema","text":"Ang nakatagong sanhi sa likod ng isa o higit pang incident. Pinagsasama ng 🧩 problem card ang mga incident na paulit-ulit na bumabalik, para mahanap ang sanhi at maayos ito nang tuluyan.","also":["mga problema","problem","problems"],"noTip":1},{"id":"rootcause","g":"run","word":"Root cause","text":"Ang tunay na dahilan kung bakit may nasira, hindi lang ang nakita mong nagkamali. Ayusin ang root cause at hindi na babalik ang incident.","also":["root causes","ugat ng problema"]},{"id":"workaround","g":"run","word":"Workaround","text":"Paraan para patuloy na gumana ang mga bagay habang hindi pa handa ang totoong ayos, gaya ng pag-restart ng isang bagay kapag na-stuck ito. Nakasulat ito sa problem card para wala nang kailangang mag-isip nito ulit.","also":["workarounds","pansamantalang solusyon"]},{"id":"knownerror","g":"run","word":"Known error","text":"Problemang nauunawaan na ang sanhi pero hindi pa naaayos, kadalasan may nakasulat na workaround. Inililista ito ng 🧩 Known errors, para ang lahat ay gumamit ng workaround sa halip na maghukay ulit.","also":["known errors"]},{"id":"runbook","g":"run","word":"Runbook","text":"Sunud-sunod na instruksyon para ayusin ang kilalang uri ng problema, para pareho at mabilis itong magawa sa bawat pagkakataon. Pagkatapos ng malaking incident, puwedeng magmungkahi ang team ng isa para i-OK mo.","also":["runbooks"]},{"id":"ci","g":"run","word":"Configuration item","text":"Isang bagay na inaasahan ng service mo, gaya ng server, domain, certificate, key o supplier. Inililista ng 🗂️ Configuration items ang mga ito bawat service, para makita mo kung ano ang naaapektuhan ng isang incident at ano ang kailangang i-renew o i-back up.","also":["configuration items","CI"]},{"id":"expiry","g":"run","word":"Expiry date","text":"Ang petsang hihinto sa paggana ang isang bagay maliban kung ire-renew, tulad ng security certificate ng website o ang web address nito. Binabantayan ng AI-gile ang mga petsang ito at gumagawa ng isang card para i-renew ang bawat isa 30 araw bago, para walang biglang tumigil.","also":["expiry dates","expiry","petsa ng pag-expire","expiry watch"]},{"id":"backup","g":"run","word":"Backup","text":"Isang naka-save na kopya ng data mo mula dati, na mababalikan kung may mawala o masira. Gumagawa ang AI-gile ng backup ng mga board mo araw-araw.","also":["backups","back-up","mga backup"]},{"id":"restore","g":"run","word":"Restore","text":"Pagbabalik ng data mula sa backup. Talagang may silbi lang ang backup kapag alam mong kaya itong i-restore, kaya sulit na subukan ito paminsan-minsan.","also":["i-restore","na-restore","ibalik"]},{"id":"svcreview","g":"run","word":"Service review","text":"Pagbabalik-tanaw sa isang buwan ng isang service: mga incident na binuksan at naayos, gaano kabilis nakakuha ng sagot ang mga tao, uptime at mga token na nagamit. Ipinapakita ito ng Buwanang review para sa bawat service.","also":["service reviews","buwanang review","monthly review"]},{"id":"accessreview","g":"run","word":"Access review","text":"Pagsusuri tuwing 90 araw kung sino pa ang nakakapasok: mga share link, role ng mga kaibigan at mga naka-save na password at susi. Ikaw ang magpapasya kung itatago o aalisin ang bawat isa, para hindi maiwan ang lumang access.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Lahat ng napagpasyahan ng team na pagbutihin, nasa iisang lugar: retro suggestions, review actions at problem fixes, bawat isa may status. Makikita ito sa 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"Buwanang limit sa mga token na puwedeng gamitin ng mga agent ng isang service. Sa 80% may babala ka; sa 100% maghihintay ang background work nila hanggang sa susunod na buwan o hanggang itaas mo ang cap.","also":["token caps","buwanang token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Lahat ng kailangan para manatiling kapaki-pakinabang at gumagana ang isang serbisyo para sa mga umaasa rito, araw-araw."},{"id":"itil","g":"run","word":"ITIL","text":"Malawakang ginagamit na gabay sa mahusay na service management, na sumasaklaw sa mga incident, problema at pagbabago. Dating ibig sabihin ng pangalan ay IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Pagpapatakbo ng teknolohiya bilang serbisyo para sa mga tao, na may malinaw na paraan sa paghawak ng mga hiling, incident, pagbabago at pagpapabuti.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"Serbisyong ibang tao ang nagpapatakbo at nag-aalaga para sa iyo, ayon sa kasunduan kung gaano ito kahusay dapat gumana.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"Taong sumasagot para sa buong serbisyo: gaano ito kahusay gumana, magkano ang gastos at paano ito gumaganda.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"Nakasulat na pangako sa mga customer kung gaano kahusay gagana ang serbisyo, tulad ng “gumagana 99.9% ng oras” o “sinasagot sa loob ng isang oras”, madalas na may refund kapag hindi natupad.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"Sariling target ng team kung gaano kahusay dapat gumana ang serbisyo sa isang panahon, kadalasang bahagyang mas mahigpit kaysa SLA para sigurado.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"Ang aktuwal na sukat na sinusuri laban sa target, tulad ng bahagi ng mga pagbisitang maayos na nag-load.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Kung magagamit ng mga tao ang serbisyo kapag kailangan nila ito, madalas na sinusukat bilang uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Oras na hindi gumagana o nakapatay ang serbisyo, planado man o hindi.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"Ang maliit na dami ng pagpalya na pinapayagan ng target mo sa pagiging maaasahan. Habang may natitira pa, puwede kang sumugal sa mga pagbabago; kapag naubos na, magdahan-dahan ka.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"Panahong patay o malubhang sira ang serbisyo para sa mga user nito.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Gumagana, pero hindi maayos: mabagal, o may ilang bahaging hindi gumagana.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Awtomatiko at tuloy-tuloy na pagbabantay sa serbisyo, para makita ang mga problema, mas mainam bago pa mapansin ng mga user."},{"id":"observability","g":"run","word":"Observability","text":"Gaano mo kahusay malalaman mula sa labas kung ano ang nangyayari sa loob ng sistema, gamit ang mga log, numero at trace nito.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"Patuloy na talaarawan ng isang programa ng ginagawa nito, ginagamit para malaman kung ano ang nagkamali.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"Rekord kung paano naglalakbay ang isang hiling sa iba’t ibang bahagi ng sistema, hakbang-hakbang, na nagpapakita kung saan ito bumagal.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"Gaano katagal bago sumagot ang isang bagay, tulad ng paghihintay sa pagitan ng pagpindot at paglabas ng pahina."},{"id":"alert","g":"run","word":"Alert","text":"Awtomatikong mensahe na may kailangang tutukan, tulad ng hindi pagsagot ng website.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"Kapag napakarami ng alert na hindi na pinapansin ng mga tao, pati ang mahahalaga.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"Screen na nagpapakita ng pinakamahahalagang numero at katayuan sa isang tingin.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Apurahang pagtawag o paggising sa taong naka-on-call tungkol sa isang problema.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Pagsama ng may mas mataas na kasanayan o awtoridad kapag hindi maayos ang isyu sa kasalukuyang antas, o hindi sapat ang bilis.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Mabilis na pag-uuri sa mga dumarating na isyu ayon sa pagkaapurahan at kahalagahan, para unang maasikaso ang pinakamalala.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"Gaano kalaki ang epekto ng isang bagay sa mga tao: ilan ang apektado, at gaano kalala.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"Gaano kabilis kailangang asikasuhin ang isang bagay. Ang impact at urgency ang magkasamang nagtatakda ng priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Mga label ng pagkaapurahan ng isyu. Ang P1 ang pinakaseryoso at kailangang kumilos agad.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"Ang listahan ng mga hiling at incident na naghihintay na kunin.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line at second line","text":"Mga antas ng suporta: sumasagot ng tawag ang first line at inaayos ang mga simpleng bagay; mas malalim ang kasanayan ng second line para sa mas mahihirap. Tinatawag ding tier 1 at tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"Ang nag-iisang taong namumuno sa pagtugon sa isang incident, para alam ng lahat kung sino ang nagpapasya at sino ang gumagawa ng ano.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"Gaano katagal bago may unang kumuha ng isang hiling o incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"Gaano katagal bago lubusang maayos ang isang hiling o incident, mula sa pag-uulat hanggang sa maayos ito.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"Sa karaniwan, gaano katagal bago gumana ulit ang serbisyo pagkatapos masira. Maaaring bahagyang magkaiba ang kahulugan ng MTTR, kaya sabihin kung ano ang sinusukat mo.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"Sa karaniwan, gaano katagal tumatakbo ang serbisyo bago may masira.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"Ang listahan ng lahat ng configuration item mo at kung paano sila magkakaugnay, para makita kung ano ang nakadepende sa ano.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anumang may halagang pag-aari mo o binabayaran mo para patakbuhin ang serbisyo, tulad ng laptop, lisensya ng software o domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Pagtiyak na may sapat na lakas ng computer, imbakan at tao para sa darating.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Pagharap sa mas maraming user sa pamamagitan ng pagdagdag ng lakas sa isang makina (scaling up) o pagdagdag ng mas maraming makina (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Mga plano para magpatuloy ang mahahalagang bagay kapag may malaking pumalpak, tulad ng pagkawala ng opisina, pangunahing supplier o mga computer.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"Ang plano at mga tool para maibalik ang serbisyo pagkatapos ng seryosong pangyayari, tulad ng pagkawala ng buong data center.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"Ang pinakamatagal na puwedeng patay ang serbisyo pagkatapos ng sakuna bago ito dapat gumana ulit.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"Gaano karaming kamakailang data ang kaya mong mawala, sinusukat sa oras. Ang RPO na isang oras ay nangangahulugang may backup nang hindi bababa sa bawat oras.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Pagkakaroon ng handang reserba, tulad ng pangalawang server, para hindi mapahinto ng isang pagkasira ang serbisyo."},{"id":"failover","g":"run","word":"Failover","text":"Awtomatikong paglipat sa reserbang sistema kapag nasira ang karaniwan.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"Isang bahaging nagpapabagsak sa lahat kapag nasira, dahil walang reserba.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"Planadong oras na puwedeng ihinto o bumagal ang serbisyo para sa pagpapanatili, ipinaaalam sa mga user nang maaga.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Pagpasa ng trabaho, kaalaman at pananagutan sa ibang tao o team, para walang malaglag.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"Koleksyon ng mga artikulong tulong at sagot, para sa mga user at sa team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"Marka mula sa mga user kung gaano sila natuwa, madalas itinatanong pagkatapos maisara ang isang hiling.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"Panlabas na kumpanyang inaasahan mo, tulad ng hosting provider mo. Tinatawag ding vendor o third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Ligtas at permanenteng pagpatay sa isang serbisyo: pagsabi sa mga user nito, pag-asikaso sa data at access nito, at pagtigil sa mga gastos nito.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"Kapag huminto na ang gumawa ng produkto sa pagbibigay ng update o suporta, kaya dapat na itong palitan.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Pagprotekta sa mga sistema at data laban sa panghihimasok, pagnanakaw o pagkasira.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Pagsuri kung sino ang isang tao, kadalasan sa password o code. Madalas pinaiikli bilang authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorization","text":"Pagsuri kung ano ang pinapayagang gawin ng isang tao kapag alam mo na kung sino siya. Madalas pinaiikli bilang authz.","also":["authz","authorisation"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Pag-log in gamit ang dalawa o higit pang patunay, tulad ng password at code sa telepono mo. Tinatawag ding two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Isang beses na pag-log in para makapasok sa maraming sistema, tulad ng paggamit ng account mo sa trabaho kahit saan.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"App na gumagawa ng matitibay na password at naaalala ang mga ito para sa iyo.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"Password, susi o iba pang pribadong code na ginagamit ng programa para makapasok sa isang bagay. Hindi ito dapat ibahagi o isulat sa code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"Lihim na code na nagpapahintulot sa programa na gamitin ang API ng ibang serbisyo, at nagpapakita kung sino ang gumagamit (at nagbabayad).","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"Pansamantalang pass na nagpapatunay na pinapayagang pumasok ang programa, kaya hindi na nito kailangan ang password mo sa bawat pagkakataon. Hindi ito kapareho ng AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Pag-scramble sa impormasyon para ang may tamang susi lang ang makabasa nito.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Ang ligtas na paraan ng paglalakbay ng mga web page, na ipinapakita ng padlock sa browser mo, para walang nasa gitna ang makakabasa o makakabago."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"Digital na ID card na nagpapahintulot sa website na patunayan kung sino ito at gumamit ng HTTPS. Nag-e-expire ito, kaya kailangang i-renew.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"Ang mga patakaran kung sino ang puwedeng makakita o magbago ng ano.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Pagbibigay sa bawat tao o programa ng access na talagang kailangan lang nila, at sa tagal lang na kailangan nila.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Pagbibigay ng access ayon sa role, tulad ng viewer o editor, sa halip na isa-isang tao.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"Kahinaang puwedeng gamitin ng sinuman para pumasok o makapinsala.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Kahinaang alam na ng mga umaatake bago pa magkaroon ng oras ang mga gumawa para ayusin ito.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Mapaminsalang software, tulad ng mga virus, na ginawa para manira, magmanman o magnakaw."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware na nagla-lock ng mga file mo at humihingi ng pera para buksan ang mga ito. Ang magagandang backup ang pinakamahusay na depensa.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Mga pekeng mensaheng sinusubukan kang lokohin para ibigay ang password o pera, o magbukas ng mapaminsalang bagay.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Panloloko sa mga tao, hindi sa computer, para makakuha ng access, tulad ng pekeng tawag mula sa “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"Bantay na nagpapasya kung aling trapiko ng network ang puwedeng pumasok o lumabas.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Maikli para sa virtual private network: pribado at naka-scramble na koneksyon sa internet, madalas gamitin para ligtas na maabot ang mga sistema sa trabaho.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Pagbaha sa serbisyo ng napakaraming pekeng trapiko kaya hindi na ito magamit ng totoong tao. Ang DDoS ay galing sa maraming computer nang sabay.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Pag-hire ng mapagkakatiwalaang eksperto na susubukang pumasok, para makita ang mga kahinaan bago pa makita ng totoong mga umaatake.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"Maingat na pagsusuri kung gaano kahusay protektado ang isang bagay, laban sa listahan ng mabubuting gawi.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modeling","text":"Pag-iisip kung sino ang maaaring umatake, paano, at ano ang gagawin mo para pigilan sila.","also":["threat model","threat modelling"]},{"id":"breach","g":"sec","word":"Data breach","text":"Kapag lumabas ang pribadong impormasyon sa mga taong hindi dapat magkaroon nito, o nawala o nabago nang walang pahintulot.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Anumang impormasyon tungkol sa taong matutukoy, tulad ng pangalan, email address o lokasyon. Tinatawag ding PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Ang batas ng Europa tungkol sa personal na data (may sariling bersyon ang UK): kunin lang ang kailangan, panatilihing ligtas, at hayaang makita o mabura ng mga tao ang kanila.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Maayos na pag-aalaga sa personal na data at ayon sa batas.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"Pampublikong pahinang nagsasabi kung anong personal na data ang kinukuha mo, bakit, at ano ang ginagawa mo rito.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"Malinaw at malayang “oo” ng isang tao na gamitin ang data niya sa partikular na paraan. Puwede niya itong bawiin anumang oras.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"Maliit na file na sine-save ng website sa browser mo para may maalala, tulad ng pagiging naka-log in. Ang ilan ay nangangailangan muna ng pahintulot mo.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimization","text":"Pagkuha at pag-iingat lang ng personal na data na talagang kailangan mo para sa trabaho.","also":["data minimisation"]},{"id":"retention","g":"sec","word":"Data retention","text":"Gaano katagal itinatago ang data bago ito burahin. Mas ligtas, at madalas batas din, na huwag itong itago nang lampas sa kailangan.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymization","text":"Pagbabago ng data para wala nang makakilala sa sinuman mula rito nang makatwiran.","also":["anonymised","anonymization","anonymous data","anonymisation"]},{"id":"pseudo","g":"sec","word":"Pseudonymization","text":"Pagpapalit ng mga pangalan at iba pang detalye ng mga code, na may hiwalay na susi para maibalik ang ugnayan. Personal na data pa rin ito.","also":["pseudonymised","pseudonymisation"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"Kontratang nagsasabi kung paano puwedeng hawakan ng supplier ang personal na data para sa iyo.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"Maingat na pagtingin, bago magsimula, kung paano maaapektuhan ang mga tao ng planong gumamit ng personal na data at paano babawasan ang mga panganib.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"Talaan kung sino ang gumawa ng ano at kailan, para masuri ang mga kilos sa kalaunan.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Pagsunod sa mga batas, patakaran at pamantayang sumasaklaw sa iyo, at kakayahang patunayang sumusunod ka.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Kilalang pandaigdigang pamantayan sa pamamahala ng seguridad ng impormasyon. Puwedeng ma-certify ang mga kumpanya rito.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Ulat mula sa US, sinuri ng mga panlabas na auditor, na nagpapakitang maayos na iniingatan ng kumpanya ang data ng mga customer.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI na mag-isang gumagawa sa isang task: nagbabasa ng code, gumagawa ng mga pagbabago, nagpapatakbo ng mga tsek at nag-uulat pabalik. Sinusuri pa rin ang gawa nito.","also":["agent","mga agent"]},{"id":"token","g":"ai","word":"Token","text":"Ang maliliit na piraso ng teksto na binabasa at isinusulat ng AI, mga tatlong-kapat ng isang salita bawat isa. Binibilang sa token ang paggamit ng AI, kaya mas kaunting token ay mas maraming natitira sa plan mo.","also":["token","mga token"]},{"id":"hook","g":"ai","word":"Hook","text":"Maliit na command na kusang tumatakbo sa takdang sandali, halimbawa kapag nagsimula ang AI session, para marinig ng team ang mga komento mo.","also":["hook","mga hook"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Mga computer system na gumagawa ng mga bagay na karaniwang akala natin ay nangangailangan ng tao, tulad ng pagsusulat, pagsagot sa mga tanong o pagkilala sa mga larawan.","also":["AI","artificial intelligence","artipisyal na katalinuhan"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"Paraan para matuto ang mga computer ng mga pattern mula sa maraming halimbawa, sa halip na bigyan ng eksaktong mga patakaran.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Ang sinanay na “utak” ng isang AI system, binuo sa pag-aaral mula sa napakaraming halimbawa. Magkakaiba ang mga model sa husay, bilis at presyo.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"AI model na sinanay sa napakaraming teksto, kaya nakakabasa at nakakasulat ito ng wika.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI na lumilikha ng mga bagong bagay, tulad ng teksto, larawan o code, sa halip na mag-uri-uri o kumilala lang ng mga ito.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Programang kausap mo sa pang-araw-araw na wika, sa pag-type o pagsasalita.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"Ang ibinibigay mo sa AI: ang tanong o tagubilin mo, kasama ang anumang iaabot mo rito. Mas malinaw na prompt, kadalasan mas mahusay na sagot.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"Ang kasanayan sa pagsulat ng mga prompt na nagbibigay ng maaasahan at kapaki-pakinabang na resulta."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Mga tagubiling nasa likod na natatanggap ng AI bago magsimula ang usapan, na nagtatakda ng role at mga patakaran nito. Mas mabigat ang mga ito kaysa sa tina-type mo.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Lahat ng nakikita ng AI habang gumagawa: ang mga tagubilin, mga mensahe mo, mga file na nabasa na nito at mga naunang sagot.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"Gaano karami ang kayang itago ng AI sa isip nang sabay, sinusukat sa token. Lampas doon, ang mas lumang bahagi ay itinatapon o binubuod.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"Isang usapang pangtrabaho sa AI, mula simula hanggang wakas. Ang bagong session ay nagsisimula sa malinis na memorya.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Mga tala na iniingatan ng AI sa pagitan ng mga session, para maalala nito ang mga gusto mo at mga nakaraang desisyon.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"Kapag may sinabi ang AI na mukhang sigurado pero gawa-gawa lang o mali. Suriin ang mahahalagang katotohanan.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Pagtuturo sa isang model sa pamamagitan ng pagpapakita ng napakaraming halimbawa, bago ito gamitin ng sinuman.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"Ang mga halimbawang pinagmulan ng pag-aaral ng model. Natitigil ang kaalaman nito sa petsang kinolekta ang data na iyon.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"Ang petsa kung kailan nagtatapos ang kaalamang nakapaloob sa AI. Hindi nito alam ang mga sumunod na pangyayari maliban kung hahanapin nito.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Dagdag na pagsasanay sa kasalukuyang model gamit ang sarili mong mga halimbawa, para gumaling ito sa isang partikular na trabaho.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"Ang aktuwal na paggamit ng AI model para sagutin ang isang bagay, kaiba sa pagsasanay nito.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"Kakayahan ng AI na gumawa ng mga bagay, hindi lang magsalita: magpatakbo ng mga command, magbasa ng mga file o maghanap sa web, sa pamamagitan ng mga tool na ibinibigay ng app.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Katulong na AI na pinag-aabutan ng pangunahing AI ng mas maliit na trabaho, at binabalikan ng resulta.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Ilang AI na magkakasamang gumagawa sa iisang trabaho, bawat isa may sariling bahagi, parang maliit na team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"Gaano karami ang puwedeng gawin ng AI nang mag-isa bago kailangang magtanong sa tao.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Pagpapanatili ng tao sa proseso para suriin o aprubahan ang ginagawa ng AI sa mahahalagang punto. Sa AI-gile, ikaw iyon.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Mga limitasyon at tsek na nagpapanatiling ligtas ang mga kilos ng AI, tulad ng pangangailangan ng pag-apruba bago mag-live ang anuman. Binabawasan nila ang panganib ng pagkakamali, pero hindi nila ito inaalis.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Pagpapahintulot sa AI na maghanap sa sarili mong mga dokumento bago sumagot, para nakabatay sa iyong mga katotohanan ang mga sagot nito.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Pag-convert ng teksto sa listahan ng mga numero na sumasalamin sa kahulugan nito, para makahanap ang computer ng mga bagay na magkahawig ang kahulugan.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"Database na ginawa para maghanap sa mga listahan ng numerong iyon (embeddings), para makahanap ng materyal na magkapareho ang kahulugan.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Karaniwang paraan para isaksak ang mga tool at pinagkukunan ng data sa mga AI app, para magamit ito ng AI.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"Setting kung gaano kapangahas ang mga sagot ng AI. Ang mababa ay nagbibigay ng mas matatag at mahuhulaang sagot; ang mataas ay mas iba-iba. Pero walang setting na magpapatama rito palagi.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Kayang gumamit ng higit sa isang uri ng impormasyon, tulad ng teksto, larawan at tunog.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"Planadong pagsubok kung gaano kahusay ang AI sa mga piniling halimbawa, para maihambing ang mga model o prompt.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"Kapag ang AI (o tao) ay hindi patas na kumikiling sa isang panig, madalas dahil sa pinagmulan ng natutunan nito.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Paggamit ng AI nang patas, ligtas at tapat, na ang mga tao pa rin ang sumasagot sa mga resulta.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"Panlilinlang kung saan sinusubukan ng mga nakatagong tagubilin sa isang web page o file na pagawin sa AI ang bagay na hindi hiniling ng user nito.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"Hangganan sa dami ng hiling na puwede mong ipadala sa serbisyo sa takdang oras. Kapag lumampas, maghihintay ka.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"Gaano karaming trabaho ng AI ang pinapayagan ng plan mo sa isang panahon, na pagkatapos nito ay hihinto ito o may dagdag na bayad.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Pagbuo ng software na kadalasan ay inilalarawan mo lang sa AI ang gusto mo at hinahayaan mo itong magsulat ng code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"Halagang inilaan para sa isang bagay.","also":["budgets","badyet"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"Pinakamagandang hula kung magkano ang magagastos sa isang bagay bago magsimula.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"Ang nakukuha mong balik kumpara sa inilagay mo. Kapag positibo, sulit ito.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Lahat ng talagang magagastos sa isang bagay sa buong buhay nito, hindi lang ang presyo ng pagbili: pagpapatakbo, suporta, mga upgrade at sa huli ang pagreretiro rito.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx at OpEx","text":"Ang CapEx ay perang ginagastos sa umpisa para sa mga bagay na mananatili sa iyo; ang OpEx ay tuloy-tuloy na gastos, tulad ng buwanang bayarin.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Regular na pagbabayad, karaniwang buwanan o taunan, para patuloy na magamit ang isang bagay.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software na ginagamit mo online at binabayaran sa pamamagitan ng subscription, habang ang gumawa ang nagpapatakbo nito para sa iyo.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Pagbabayad lang sa ginamit mo, tulad ng cloud computing o AI token.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Paggamit na lampas sa kasama sa plan mo, na maaaring may dagdag na bayad.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"Mensahe kapag umabot sa antas na pinili mo ang gastos o paggamit. Nagbababala ito, pero hindi laging pumipigil sa karagdagang singil.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"Libreng antas ng bayad na serbisyo, may mga limitasyon. Mainam para sa pagsisimula.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"Ang iba’t ibang package na ibinebenta ng serbisyo, bawat isa may sariling presyo at limitasyon.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"License","text":"Ang mga patakaran kung paano mo puwedeng gamitin, kopyahin, baguhin o ibahagi ang ginawa ng iba, tulad ng software, font o larawan.","also":["licences","licenses","licence","lisensya"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software na ang code ay mababasa, magagamit at madalas mababago nang libre ninuman, ayon sa mga patakaran ng lisensya nito.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source license","text":"Ang mga patakarang kasama ng open source code. May ilang halos lahat ay pinapayagan (tulad ng MIT); may ilang humihiling na ibahagi mo rin ang mga pagbabago mo (tulad ng GPL).","also":["open source licences","MIT licence","GPL","open source licenses"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Pag-aari ng isang kumpanya at hindi libreng kopyahin o baguhin. Kabaligtaran ng open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"Legal na karapatan ng lumikha na kontrolin ang mga kopya ng gawa niya, kasama ang code at sulatin.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Mga ideya at likhang itinuturing ng batas na pag-aari, tulad ng code, disenyo, pangalan at logo.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"Ang mga patakarang sinasang-ayunan mo kapag gumagamit ka ng serbisyo.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"Nakasulat na kasunduan ng dalawang panig na susuportahan ng batas.","also":["contracts","kontrata"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"Dokumentong nagtatakda nang eksakto kung anong trabaho ang gagawin, hanggang kailan at sa halagang magkano.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"Napagkasunduang presyo para sa buong trabaho, gaano man katagal.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Pagbabayad para sa mga oras na talagang ginugol at mga bagay na talagang nagamit, hindi takdang presyo.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"Singil na humihingi ng bayad para sa nagawang trabaho o naibigay na produkto.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"Kapag napakahirap o napakamahal lumayo sa isang supplier kaya hindi ka makaalis.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"Ang proseso ng pagpili at pagbili mula sa mga supplier."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Perang ibinalik o diskwentong nakukuha mo kapag hindi natupad ng supplier ang SLA nito.","also":["service credits"]}]}};
